def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator lattice locations: recurring rows/columns dominated by 2.
    rows = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w - 3]
    cols = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h - 3]

    out = []
    for r1, r2 in zip(rows, rows[1:]):
        line = []
        for c1, c2 in zip(cols, cols[1:]):
            # The encoded color is marked along the right border of each tile.
            a, b = grid[r1][c2], grid[r2][c2]
            if a == b and a not in (0, 2):
                line.append(a)
            else:
                line.append(9)
        out.append(line)
    return out
